pm.test("Invalid website returns HTTP 400", function () {
    pm.response.to.have.status(400);
});

pm.test("Correct error message is returned", function () {
    const response = pm.response.json();
    pm.expect(response.detail).to.eql("Website not allowed");
});

pm.test("Valid website returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Correct website is returned", function () {
    const response = pm.response.json();
    pm.expect(response.website).to.eql("example.com");
});

pm.test("HTTP monitoring data is present", function () {
    const response = pm.response.json();
    pm.expect(response).to.have.property("http_monitoring");
});
